/**
 * A long read: sections with headings, text and an optional pull quote, in one reading column or beside a table
 * of contents that links to each section. Axes: layout (column, toc), quotes (show, hide), tone. Highlighting
 * the section being read is a port contract.
 */
import { For, type JSX } from "solid-js";
import { Box } from "../primitives/box/box";
import { Grid } from "../primitives/grid/grid";
import { Link } from "../primitives/link/link";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { NavBlock } from "../components/nav-block";
import { SectionFrame } from "../components/section-frame";
import { cn, tpl, uniqLabel } from "../utils";
import type { Section } from "./article-body.types";

export type ArticleBodyProps = {
  id: string;
  title: string;
  sections: Section[];
  tocTitle: string;
  layout?: "column" | "toc";
  quotes?: "show" | "hide";
  tone?: "default" | "muted";
  landmarkLabel?: string;
};

export function ArticleBody({
  id,
  title,
  sections,
  tocTitle,
  layout = "column",
  quotes = "show",
  tone = "default",
  landmarkLabel,
}: ArticleBodyProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone} landmarkLabel={landmarkLabel}>
      <Grid
        cols="1"
        class={cn(
          "items-start gap-8",
          (((layout as string) === "toc") ? "md:grid-cols-[14rem_minmax(0,1fr)]" : "")
        )}
      >
        {((layout as string) === "toc") ? (
          <NavBlock
            label={(landmarkLabel ? uniqLabel(tpl("{0}, {1}", tocTitle, landmarkLabel)) : tocTitle)}
            class="md:sticky md:top-4"
            testid="toc"
          >
            <Stack gap="2">
              <Text size="sm" weight="semibold">
                {tocTitle}
              </Text>
              <List class="m-0 flex list-none flex-col gap-2 p-0">
                <For each={sections ?? []}>{(s) => (
                  <ListItem>
                    <Link
                      href={tpl("#{0}-{1}", id, s.id)}
                      variant="default"
                      class="text-sm text-muted-foreground"
                      data-testid="toc-link"
                    >
                      {s.title}
                    </Link>
                  </ListItem>
                )}</For>
              </List>
            </Stack>
          </NavBlock>
        ) : null}
        <Stack gap="8" align="stretch" class="mx-auto w-full max-w-2xl min-w-0" data-testid="article">
          <For each={sections ?? []}>{(s) => (
            <Box class="flex flex-col gap-4" id={tpl("{0}-{1}", id, s.id)} data-testid="item">
              <Title as={3} size="2xl" weight="bold">
                {s.title}
              </Title>
              <Text size="base">
                {s.text}
              </Text>
              {((quotes as string) === "show") ? (
                <>
                  {s.quote ? (
                    <Text tag="blockquote" class="m-0 border-l border-border pl-4 text-lg" data-testid="quote">
                      {s.quote}
                    </Text>
                  ) : null}
                </>
              ) : null}
            </Box>
          )}</For>
        </Stack>
      </Grid>
    </SectionFrame>
  );
}

